package com.ventas.service;
import com.ventas.dto.XmlTrialModels.*;import java.util.*;import java.math.BigDecimal;import java.io.*;import java.nio.charset.StandardCharsets;import javax.xml.parsers.DocumentBuilderFactory;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class XmlTrialRendererTest{
 XmlTrialRenderer renderer=new XmlTrialRenderer();Document sample(){return XmlTrialService.example("B");}
 Document copy(Document d,String type,String state,String tax,String customerDoc,BigDecimal total,List<Line> lines){return new Document(d.venta(),type,d.serie(),d.numero(),d.fecha(),d.emisor(),d.ruc(),d.direccion(),d.cliente(),d.tipoDocumento(),customerDoc,d.porcentaje(),d.base(),d.igv(),total,state,d.estadoComprobante(),tax,lines);}
 org.w3c.dom.Document parse(String xml)throws Exception{var f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);return f.newDocumentBuilder().parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));}
 @Test void generatesWellFormedTrialWithNoSignature()throws Exception{var p=renderer.preview(sample());assertThat(p.generable()).isTrue();assertThat(p.validezTributaria()).isFalse();assertThat(p.enviosHabilitados()).isFalse();var xml=parse(p.xml());assertThat(xml.getDocumentElement().getLocalName()).isEqualTo("Invoice");assertThat(xml.getElementsByTagNameNS("*","UBLVersionID").item(0).getTextContent()).isEqualTo("2.1");assertThat(p.xml()).contains(XmlTrialRenderer.WARNING,"12:00:00").doesNotContain("<ds:Signature","<Signature");}
 @Test void anonymousBoletaDoesNotInventDni()throws Exception{var xml=parse(renderer.preview(sample()).xml());var customer=xml.getElementsByTagNameNS("*","AccountingCustomerParty").item(0);assertThat(customer.getTextContent()).doesNotContain("00000000");assertThat(((org.w3c.dom.Element)customer).getElementsByTagNameNS("*","PartyIdentification").getLength()).isZero();}
 @Test void facturaUsesItsOwnDocumentType()throws Exception{var p=renderer.preview(XmlTrialService.example("F"));assertThat(p.generable()).isTrue();assertThat(parse(p.xml()).getElementsByTagNameNS("*","InvoiceTypeCode").item(0).getTextContent()).isEqualTo("01");}
 @Test void rejectsNotesCancelledAndIntegratedReceipts(){var d=sample();for(var changed:List.of(copy(d,"N","CONFIRMADA","NO_APLICA",null,d.total(),d.lineas()),copy(d,"B","ANULADA","NO_INTEGRADO",null,d.total(),d.lineas()),copy(d,"B","CONFIRMADA","ACEPTADO",null,d.total(),d.lineas()))){assertThat(renderer.preview(changed).generable()).isFalse();assertThat(renderer.preview(changed).xml()).isNull();}}
 @Test void rejectsTotalsThatDoNotReconcile(){var d=sample();assertThat(renderer.errors(copy(d,"B","CONFIRMADA","NO_INTEGRADO",null,new BigDecimal("119.00"),d.lineas()))).anyMatch(e->e.contains("concilian"));}
 @Test void rejectsMissingTaxSnapshotsAndDuplicateLines(){var d=sample();var l=d.lineas().getFirst();var missing=new Line(l.id(),l.producto(),l.presentacion(),l.unidad(),l.cantidad(),l.precio(),l.importe(),null,null);assertThat(renderer.errors(copy(d,"B","CONFIRMADA","NO_INTEGRADO",null,d.total(),List.of(missing)))).isNotEmpty();assertThat(renderer.errors(copy(d,"B","CONFIRMADA","NO_INTEGRADO",null,d.total(),List.of(l,l)))).isNotEmpty();}
 @Test void escapesProductTextInsteadOfInterpretingIt()throws Exception{var d=sample();var l=d.lineas().getFirst();var text="Tuerca & <prueba> \"especial\"";var line=new Line(l.id(),text,l.presentacion(),l.unidad(),l.cantidad(),l.precio(),l.importe(),l.base(),l.igv());var p=renderer.preview(copy(d,"B","CONFIRMADA","NO_INTEGRADO",null,d.total(),List.of(line)));assertThat(p.generable()).isTrue();assertThat(parse(p.xml()).getElementsByTagNameNS("*","Description").item(0).getTextContent()).contains(text);assertThat(p.xml()).contains("&amp;","&lt;prueba&gt;");}
 @Test void rejectsXmlControlCharacters(){var d=sample();var l=d.lineas().getFirst();var line=new Line(l.id(),"Producto"+(char)0,l.presentacion(),l.unidad(),l.cantidad(),l.precio(),l.importe(),l.base(),l.igv());assertThat(renderer.errors(copy(d,"B","CONFIRMADA","NO_INTEGRADO",null,d.total(),List.of(line)))).isNotEmpty();}
 @Test void rejectsTaxRateInconsistentWithSnapshot(){var d=sample();var changed=new Document(d.venta(),d.tipo(),d.serie(),d.numero(),d.fecha(),d.emisor(),d.ruc(),d.direccion(),d.cliente(),d.tipoDocumento(),d.documento(),new BigDecimal("20"),d.base(),d.igv(),d.total(),d.estadoVenta(),d.estadoComprobante(),d.estadoTributario(),d.lineas());assertThat(renderer.errors(changed)).anyMatch(e->e.contains("porcentaje de IGV"));}
}
